class Solution {
    fun getMaxFunctionValue(receiver:List<Int>,k:Long):Long{
        val n=receiver.size;
        val levels=61;
        val jump=Array(levels){
            IntArray(n)
        };
        val sum=Array(levels){
            LongArray(n)
        };
        for(node in 0 until n){
            jump[0][node]=receiver[node];
            sum[0][node]=receiver[node].toLong()
        };
        for(bit in 1 until levels)for(node in 0 until n){
            val middle=jump[bit-1][node];
            jump[bit][node]=jump[bit-1][middle];
            sum[bit][node]=sum[bit-1][node]+sum[bit-1][middle]
        };
        var answer=0L;
        for(start in 0 until n){
            var node=start;
            var value=start.toLong();
            for(bit in 0 until levels)if((k shr bit and 1L)==1L){
                value+=sum[bit][node];
                node=jump[bit][node]
            };
            answer=maxOf(answer,value)
        };
        return answer
    }
}

